class Solution {
    public int minimumSum(List<Integer> nums) {
        int n = nums.size();
        int[] pre = new int[n], suf = new int[n];
        pre[0] = nums.get(0); suf[n - 1] = nums.get(n - 1);
        for (int i = 1; i < n; i++) pre[i] = Math.min(pre[i - 1], nums.get(i));
        for (int i = n - 2; i >= 0; i--) suf[i] = Math.min(suf[i + 1], nums.get(i));
        long ans = Long.MAX_VALUE;
        for (int j = 1; j + 1 < n; j++)
            if (pre[j - 1] < nums.get(j) && nums.get(j) < suf[j + 1])
                ans = Math.min(ans, (long) pre[j - 1] + nums.get(j) + suf[j + 1]);
        return ans == Long.MAX_VALUE ? -1 : (int) ans;
    }
}

